    ce=[cs[j+1]-1 for j in range(len(cs)-1)]+[w-1]
    for (r0,r1) in bnds:
        shapes={}
        for j in range(len(cs)-1):
            c0,c1=cs[j],ce[j]
            cells=[(r-r0,c-c0,a[r][c]) for r in range(r0,r1+1) for c in range(c0,c1+1) if a[r][c]!=0 and a[r][c]!=sepv]
            shapes[j]=cells
        nb=[j for j,o in shapes.items() if o]
        if not nb: continue
        tcells=None;tcnt=-1
        for j in nb:
            if len(shapes[j])>tcnt: tcells,tcnt=shapes[j],len(shapes[j])
        allc=set(v for o in shapes.values() for _,_,v in o)
        tmplc={v for _,_,v in tcells}
        stampcol=(allc-tmplc or list(tmplc)[0])
        for j in nb:
            for dr,dc,v in shapes[j]:
                out[r0+dr][cs[j]+dc]=0
        for j in range(len(cs)-1):
            c0=cs[j]
            for dr,dc,_ in tcells:
                r,c=r0+dr,c0+dc
                if r<=r1 and c<w: out[r][c]=stampcol
    return out
