    sepv=list({a[0][c] for c in sepcols}|{a[r][0] for r in seprows})[0]
    # template: all non-zero, non-sep cells of the largest connected-ish shape overall (just pick the color whose cells form the max-count single shape)
    cnt={}
    for r in range(h):
        for c in range(w):
            if a[r][c] not in (0,sepv): cnt[a[r][c]]=cnt.get(a[r][c],0)+1
    tmplcolor=max(cnt,key=cnt.get)
    tc=[(r,c) for r in range(h) for c in range(w) if a[r][c]==tmplcolor]
    r0=min(r for r,c in tc); c0=min(c for r,c in tc)
    tcells={(r-r0,c-c0) for r,c in tc}
    out=[row[:] for row in a]
    bnds=[];prev=0
    for s in sorted(seprows)+[h]:
        if s-prev>1: bnds.append((prev,s-1)); prev=s+1
    cs=[0]+[x+1 for x in sepcols]
    ce=[cs[j+1]-1 for j in range(len(cs)-1)]+[w-1]
    for (r0b,r1b) in bnds:
        for j,(c0,c1) in enumerate(zip(cs,ce)):
            blkcolors={a[r][c] for r in range(r0b,r1b+1) for c in range(c0,c1+1) if a[r][c] not in (0,sepv)}
            rec=set(blkcolors)-{tmplcolor}
            if not rec: continue
            sc=next(iter(rec))
            for dr,dc in tcells:
                r,c=r0b+dr,c0+dc
                if r<h and c<w: out[r][c]=sc
    return out
